'use strict';

// MODULES //

var hasOwnProp = require( '@stdlib/assert/has-own-property' );


// VARIABLES //

// SVG path strings defined within a square bounding box having coordinates ranging from -1 to 1 along both the x and y dimensions...
var ASTERISK = 'M0.2,-1L-0.2,-1L-0.2,-0.34641L-0.76603,-0.67321L-0.96603,-0.32679L-0.4,0L-0.96603,0.32679L-0.76603,0.67321L-0.2,0.34641L-0.2,1L0.2,1L0.2,0.34641L0.76603,0.67321L0.96603,0.32679L0.4,0L0.96603,-0.32679L0.76603,-0.67321L0.2,-0.34641Z';
var DOT = 'M0.25,0A0.25,0.25,0,1,1,-0.25,0A0.25,0.25,0,1,1,0.25,0Z';
var HEXAGRAM = 'M0,-1L-0.28868,-0.5L-0.86603,-0.5L-0.57735,0L-0.86603,0.5L-0.28868,0.5L0,1L0.28868,0.5L0.86603,0.5L0.57735,0L0.86603,-0.5L0.28868,-0.5Z';
var LINE = 'M0,-1L0,1';
var STAR = 'M0,-1L-0.22452,-0.30902L-0.95106,-0.30902L-0.36327,0.11803L-0.58779,0.80902L0,0.38197L0.58779,0.80902L0.36327,0.11803L0.95106,-0.30902L0.22452,-0.30902Z';
var X = 'M-0.42426,-0.98995L-0.98995,-0.42426L-0.56569,0L-0.98995,0.42426L-0.42426,0.98995L0,0.56569L0.42426,0.98995L0.98995,0.42426L0.56569,0L0.98995,-0.42426L0.42426,-0.98995L0,-0.56569Z';

var SYMBOLS = {
	'arrow': 'arrow',
	'->': 'arrow',

	'asterisk': ASTERISK,
	'*': ASTERISK,

	'circle': 'circle',
	'o': 'circle',

	'cross': 'cross',
	'plus': 'cross',
	'+': 'cross',

	'diamond': 'diamond',
	'd': 'diamond',

	'dot': DOT,
	'.': DOT,

	'hexagram': HEXAGRAM,
	'h': HEXAGRAM,

	'line': LINE,
	'|': LINE,

	'square': 'square',
	's': 'square',

	'star': STAR,
	'pentagram': STAR,
	'p': STAR,

	'stroke': 'stroke',
	'_': 'stroke',

	'triangle': 'triangle',
	't': 'triangle',

	'triangle-down': 'triangle-down',
	'v': 'triangle-down',

	'triangle-left': 'triangle-left',
	'<': 'triangle-left',

	'triangle-right': 'triangle-right',
	'>': 'triangle-right',

	'triangle-up': 'triangle-up',
	'^': 'triangle-up',

	'wedge': 'wedge',
	'w': 'wedge',

	'x': X
};


// MAIN //

/**
* Converts a symbol alias or shorthand to a Vega symbol mark shape.
*
* ## Notes
*
* -   For symbols having a corresponding [Vega symbol mark shape][1], the function returns the shape name. Otherwise, the function returns an SVG path string.
* -   As stipulated by the [Vega documentation][1], returned SVG path strings are defined within a square bounding box having coordinates ranging from `-1` to `1` along both the x and y dimensions.
* -   If unable to resolve a shape, the function returns `null`.
*
* [1]: https://vega.github.io/vega/docs/marks/symbol/
*
* @param {string} value - symbol alias or shorthand
* @returns {(string|null)} symbol mark shape
*
* @example
* var v = symbol2shape( 'o' );
* // returns 'circle'
*
* v = symbol2shape( 'circle' );
* // returns 'circle'
*
* v = symbol2shape( 'beep' );
* // returns null
*/
function symbol2shape( value ) {
	if ( hasOwnProp( SYMBOLS, value ) ) {
		return SYMBOLS[ value ];
	}
	return null;
}


// EXPORTS //

module.exports = symbol2shape;
